<script setup>
import { Head } from '@inertiajs/vue3';
import { computed, ref } from 'vue';
const props = defineProps({ brand:Object, owner:Object, credentials:Array, dashboardUrl:String });
const copied = ref('');
const all = computed(() => props.credentials.map(item => `${item.name} (${item.role})\nاسم الدخول: ${item.username}\nكلمة المرور: ${item.password}`).join('\n\n'));
async function copy(value,key){await navigator.clipboard.writeText(value);copied.value=key;setTimeout(()=>{if(copied.value===key)copied.value=''},1800)}
</script>
<template><Head :title="`تم تجهيز ${brand.name}`"/><main class="page"><section class="card"><header><span class="mark"><i class="bi bi-check2"></i></span><small>اكتمل التجهيز بنجاح</small><h1>المطعم جاهز للعمل الحقيقي.</h1><p>بدأت ببيانات تشغيل نظيفة، والمنيو والوصفات التي اعتمدتها ما زالت في مكانها.</p></header><div class="owner"><i class="bi bi-person-badge"></i><div><small>حساب المالك</small><strong>{{owner.name}}</strong><span>اسم الدخول: <bdi>{{owner.username}}</bdi></span></div></div><section v-if="credentials.length" class="creds"><div class="heading"><div><small>تظهر مرة واحدة</small><h2>بيانات دخول الفريق</h2></div><button @click="copy(all,'all')"><i :class="copied==='all'?'bi bi-check2':'bi bi-copy'"></i>{{copied==='all'?'تم النسخ':'نسخ الكل'}}</button></div><article v-for="(item,index) in credentials" :key="item.username"><div class="person"><span>{{item.name.charAt(0)}}</span><p><strong>{{item.name}}</strong><small>{{item.role}}</small></p></div><dl><div><dt>اسم الدخول</dt><dd><bdi>{{item.username}}</bdi></dd></div><div><dt>كلمة المرور</dt><dd><bdi>{{item.password}}</bdi></dd></div></dl><button :aria-label="`نسخ بيانات ${item.name}`" @click="copy(`${item.username}\n${item.password}`,index)"><i :class="copied===index?'bi bi-check2':'bi bi-copy'"></i></button></article></section><div class="security"><i class="bi bi-shield-lock"></i><div><strong>سلّم كل حساب لصاحبه فقط.</strong><span>اطلب تغيير كلمات المرور بعد أول دخول. لن تظهر هذه البيانات مرة أخرى.</span></div></div><a class="dashboard" :href="dashboardUrl">دخول إلى لوحة التحكم <i class="bi bi-arrow-left"></i></a></section></main></template>
<style scoped>*{box-sizing:border-box}.page{display:grid;min-height:100dvh;place-items:center;padding:1rem;color:#1a2b21;background:radial-gradient(circle at 20% 10%,#e0f0e7,transparent 28rem),#f4f7f5}.card{width:min(100%,710px);padding:clamp(1.2rem,4vw,2.1rem);border:1px solid #d7e4dc;border-radius:23px;background:#fff;box-shadow:0 28px 80px -48px #173d2d}.card>header{text-align:center}.mark{display:grid;width:62px;height:62px;margin:0 auto .65rem;place-items:center;border-radius:19px;color:#fff;background:#1f6b50;font-size:1.75rem}.card header>small{color:#1f6b50;font-size:.65rem;font-weight:850}.card h1{margin:.28rem 0;font-size:clamp(1.4rem,4vw,1.9rem)}.card header p{margin:0;color:#728078;font-size:.69rem;line-height:1.8}.owner{display:flex;align-items:center;gap:.6rem;margin-top:1.1rem;padding:.75rem;border:1px solid #dbe6df;border-radius:13px;background:#f7faf8}.owner>i{display:grid;width:40px;height:40px;place-items:center;border-radius:11px;color:#1f6b50;background:#e5f2eb}.owner div,.person p{display:grid}.owner small,.heading small{color:#7a8980;font-size:.54rem}.owner strong{font-size:.72rem}.owner span{font-size:.59rem}.creds{margin-top:.9rem}.heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:.5rem}.heading h2{margin:.08rem 0;font-size:.82rem}.heading button{min-height:40px;padding:0 .6rem;border:1px solid #ccded3;border-radius:9px;color:#1f6b50;background:#f0f7f3;font:inherit;font-size:.59rem;font-weight:800}.creds article{display:grid;grid-template-columns:1fr 1.2fr 40px;align-items:center;gap:.55rem;padding:.65rem;border:1px solid #e0e8e3;border-radius:12px}.creds article+article{margin-top:.4rem}.person{display:flex;align-items:center;gap:.45rem}.person>span{display:grid;width:34px;height:34px;place-items:center;border-radius:10px;color:#fff;background:#1f6b50;font-weight:900}.person p{margin:0}.person strong{font-size:.64rem}.person small{color:#77857d;font-size:.52rem}.creds dl{display:grid;margin:0;grid-template-columns:1fr 1fr;gap:.35rem}.creds dl div{display:grid;padding:.35rem;border-radius:8px;background:#f6f8f7}.creds dt{color:#859189;font-size:.48rem}.creds dd{margin:0;font-size:.6rem;font-weight:800}.creds article>button{display:grid;width:40px;height:40px;place-items:center;border:1px solid #d8e4dd;border-radius:9px;color:#1f6b50;background:#fff}.security{display:flex;gap:.55rem;margin-top:.9rem;padding:.7rem;border:1px solid #eddaa9;border-radius:12px;color:#6c5424;background:#fffbef}.security div{display:grid}.security strong{font-size:.64rem}.security span{font-size:.55rem;line-height:1.65}.dashboard{display:flex;min-height:48px;align-items:center;justify-content:center;gap:.35rem;margin-top:.9rem;border-radius:11px;color:#fff;background:#1f6b50;font-size:.7rem;font-weight:850;text-decoration:none}@media(max-width:600px){.page{padding:0}.card{min-height:100dvh;border:0;border-radius:0}.creds article{grid-template-columns:1fr 40px}.creds dl{grid-column:1/-1;grid-row:2}.creds article>button{grid-column:2;grid-row:1}.dashboard{position:sticky;bottom:.7rem}}</style>
